mapper.update:
UPDATE coupon
SET status = 1,
    order_no = #{orderNo},
    discount_amount = #{discountAmount},
    lock_time = #{now},
    update_time = #{now}
WHERE id = #{couponId}
  AND user_id = #{userId}
  AND status = 0
  AND #{now} BETWEEN start_time AND end_time

UPDATE coupon
SET status = 2,
    use_time = #{now},
    update_time = #{now}
WHERE id = #{couponId}
  AND user_id = #{userId}
  AND status = 1
  AND #{now} BETWEEN start_time AND end_time
